# Re-enable Cortana (Note: App cannot be restored, only registry settings) Write-Host "Re-enabling Cortana settings..." -ForegroundColor Cyan Remove-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\Windows Search" -Name "AllowCortana" -ErrorAction SilentlyContinue Remove-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\Windows Search" -Name "DisableWebSearch" -ErrorAction SilentlyContinue Remove-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\Windows Search" -Name "AllowSearchToUseLocation" -ErrorAction SilentlyContinue Write-Host "Cortana registry settings have been restored." -ForegroundColor Green Write-Host "Note: The Cortana app was removed and needs to be reinstalled from Microsoft Store if needed." -ForegroundColor Yellow